/**
 * Disclaimer bar at the bottom of the experience center.
 *
 * Purpose: note that trial content is generated by AI and does not represent the platform's position, and offer entries for the disclaimer / test agreement / privacy policy. The experience center is an independent full-screen shell and does not show the filing record (the filing record already stays on the login page and on business pages under AdminLayout), so this only carries "AI-generated disclaimer + agreement links." Link targets reuse the existing legal documents (terms/privacy).
 *
 * @param className Extra container class name, for fine-tuning spacing/background in the layout.
 */
import { useTranslation } from 'react-i18next';

interface PlaygroundFooterProps {
  className?: string;
}

export function PlaygroundFooter({ className = '' }: PlaygroundFooterProps) {
  const { t } = useTranslation('playground');
  const base = import.meta.env.BASE_URL;
  return (
    <footer
      className={`flex flex-wrap items-center justify-center gap-x-4 gap-y-1 px-4 py-4 text-center text-xs text-muted-foreground ${className}`}
    >
      <span>{t('footerDisclaimer')}</span>
      <LegalLink href={`${base}legal/terms`}>{t('disclaimer')}</LegalLink>
      <LegalLink href={`${base}legal/privacy`}>{t('privacyPolicy')}</LegalLink>
    </footer>
  );
}

/** Agreement link: open the matching legal document in a new tab */
function LegalLink({ href, children }: { href: string; children: string }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="transition-colors hover:text-foreground"
    >
      {children}
    </a>
  );
}
